        "reference": "{base url}/{firm_url_prefix}/Patient/7132",
        "display": "{base url}/{firm_url_prefix}/ema/fhir/v2/Patient/7132"
    },
   "content": 
         [{
               "attachment": 
               {
                   "title": "Mike's PDF",
                   "contentType": "application/pdf",
